            "parent_gender": 60,
            "keywords": [131, 126],
            "meta_keywords": "zhvillimi i fëmijës, shëndeti i fëmijës, vaksinimi",
            "cover_image": {
                "url": "https://bebbo.app/sites/default/files/styles/content_1200xh_/public/2022-06/6d0a4225.webp?itok=YC7wGWLE",
                "name": "6D0A4225.JPG",
                "alt": "Inferimierja duke vlerësuar shëndetin e fëmijës"
            },
